import { readFile } from 'node:fs/promises';
import { createInterface } from 'node:readline';

// This MCP server only advertises schemas and returns a handoff notice. It
// never imports subprocess APIs, reads requested paths, or executes tool input.
// The manifest is generated by the adapter in its private request directory.
const tools = JSON.parse(await readFile(process.argv[2], 'utf8'));
const names = new Set(tools.map(tool => tool.name));
const send = value => process.stdout.write(JSON.stringify(value) + '\n');
const input = createInterface({ input: process.stdin, crlfDelay: Infinity });
for await (const line of input) {
  if (Buffer.byteLength(line) > 2 * 1024 * 1024) { process.exitCode = 1; break; }
  let message;
  try { message = JSON.parse(line); } catch { continue; }
  if (message.id === undefined) continue; // MCP notifications have no response.
  let result;
  if (message.method === 'initialize') result = {
    protocolVersion: message.params?.protocolVersion ?? '2024-11-05',
    capabilities: { tools: {} }, serverInfo: { name: 'workbuddy-client-tools', version: '1.0.0' }
  };
  else if (message.method === 'ping') result = {};
  else if (message.method === 'tools/list') result = { tools };
  else if (message.method === 'tools/call' && names.has(message.params?.name)) result = {
    isError: true, content: [{ type: 'text', text: 'CLIENT_TOOL_HANDOFF: this proxy has not executed the action. The external coding client must execute the requested tool and provide its real result in the next request.' }]
  };
  else {
    send({ jsonrpc: '2.0', id: message.id, error: { code: -32601, message: 'Method or client tool unavailable.' } });
    continue;
  }
  send({ jsonrpc: '2.0', id: message.id, result });
}
